from functools import reduce

def generator(rng):
    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // math.gcd(a, b)

    def list_lcm(numbers):
        return reduce(lcm, numbers, 1)

    while True:
        num_primes = rng.randint(4, 6)
        primes = rng.sample([2, 3, 5, 7, 11, 13, 17, 19], num_primes)

        m = rng.randint(2, 3)
        k = rng.randint(2, 3)

        s1 = set()
        for _ in range(m):
            num_factors = rng.randint(2, 3)
            factors = rng.sample(primes, num_factors)
            n = 1
            for p in factors:
                exp = rng.randint(1, 3)
                n *= p**exp
            s1.add(n)

        s2 = set()
        for _ in range(k):
            num_factors = rng.randint(2, 3)
            factors = rng.sample(primes, num_factors)
            n = 1
            for p in factors:
                exp = rng.randint(1, 3)
                n *= p**exp
            s2.add(n)

        if s1.intersection(s2):
            continue

        if len(s1) != m or len(s2) != k:
            continue

        is_redundant = False
        s1_list = list(s1)
        for i in range(len(s1_list)):
            n_i = s1_list[i]
            others = s1_list[:i] + s1_list[i+1:]
            if not others: continue
            if list_lcm(others) % n_i == 0:
                is_redundant = True
                break
        if is_redundant: continue

        s2_list = list(s2)
        for i in range(len(s2_list)):
            n_i = s2_list[i]
            others = s2_list[:i] + s2_list[i+1:]
            if not others: continue
            if list_lcm(others) % n_i == 0:
                is_redundant = True
                break
        if is_redundant: continue

        l_a = list_lcm(s1)
        l_b = list_lcm(s2)

        if l_a > 200000 or l_b > 200000:
            continue

        if any(n > 1000 for n in s1) or any(n > 1000 for n in s2):
            continue

        answer = math.gcd(l_a, l_b)

        if answer <= 10:
            continue

        s1_list_sorted = sorted(list(s1))
        s2_list_sorted = sorted(list(s2))

        return {
            'n_values': ", ".join(map(str, s1_list_sorted)),
            'm_values': ", ".join(map(str, s2_list_sorted))
        }

